  Lemma free_to_exit : forall axc s msF mo regs mem p (A cap : Z) (status : word) (pending : list byte) junk (K : TSet),
    ax_shape axc ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbeab0) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp0 - 128) -> getr regs 4 = Z_to_bv 64 ATP -> getr regs 8 = status -> getr regs 9 = Z_to_bv 64 A ->
    bv_unsigned status < 256 ->
    as_RHEAP H s [(p, A, cap)] mem -> rw_cells asegs mem A [CB (Z.to_nat cap) junk] -> addressable mem A cap ->
    as_Cf H cap <= as_AL H s ->
    xstat axc mem -> ostate pending mem ->
    (forall regs3 mem2 msF3 mo3 Lz Sz Zr,
        xstat axc mem2 -> ostate pending mem2 ->
        getr regs3 2 = Z_to_bv 64 (bv_unsigned sp0 - 48) -> getr regs3 4 = Z_to_bv 64 ATP -> getr regs3 10 = status ->
        m_fs mo3 = m_fs mo -> m_fds mo3 = m_fds mo ->
        lzok RSEGS Lz Sz Zr (mkCfg msF3 mo3) -> restrict Lz Sz msF3 = mkst regs3 (Z_to_bv 64 AEXIT) mem2 (seg_rom RSEGS) ->
        realizes asegs (mkCfg msF3 mo3) K) ->
    realizes asegs (mkCfg msF mo) K.
Proof.
